// OWNER: journey. The coast-road ROUTE: a deterministic script of stretches that the world modules (land, sea, sky)
// read by road distance, so the ride is a real journey instead of a one-second loop.
//
// Units: road distance u (the rider's frame.distance). At 60 rpm the rider covers DIST_PER_REV = 1884.96 u per second.
// One lap = LAP = 250 crank turns = 471 239 u = 250 s (4 min 10 s) at 60 rpm; LAP is an even number of crank turns so
// every near-layer tile (TILE.*, whole crank turns) lines up again at the start of each lap. The script repeats per lap,
// but everything streamed on top of it is seeded by the absolute prop index, so lap 2 is not a copy of lap 1: only the
// big set pieces (the pier, the harbour, the Ferris wheel, the lighthouse ...) come back, as landmarks do on a real road.
//
// 1 "km" on the stones = LAP / 26 = 18 124.6 u (≈ 9.6 s at 60 rpm). Stretch boundaries are in km.
// Pure data + pure functions (importable from node).
import { DIST_PER_REV } from '../contract.js';

export const LAP = 250 * DIST_PER_REV;
export const KM = LAP / 26;
const wrap = (x, m) => ((x % m) + m) % m;

// [key, from km, to km, 中文, English]; the sign for a stretch stands 0.35 km before it starts.
export const STRETCHES = [
  ['village', 0, 1.5, '鹈鹕湾', 'PELICAN BAY'],
  ['pier', 1.5, 3.5, '长堤', 'THE LONG PIER'],
  ['harbour', 3.5, 5.5, '渔港', 'FISHING HARBOUR'],
  ['funfair', 5.5, 7.5, '游乐栈桥', 'PLEASURE PIER'],
  ['railway', 7.5, 10.5, '海滨铁路', 'COAST RAILWAY'],
  ['lighthouse', 10.5, 13, '灯塔角', 'LIGHTHOUSE POINT'],
  ['cliffs', 13, 15.5, '断崖', 'THE CLIFFS'],
  ['dunes', 15.5, 18, '沙丘', 'THE DUNES'],
  ['bridge', 18, 19.5, '河口桥', 'RIVER MOUTH BRIDGE'],
  ['fort', 19.5, 21.5, '古堡浴场', 'OLD FORT & LIDO'],
  ['pines', 21.5, 24, '松林', 'PINE WALK'],
  ['return', 24, 26, '鹈鹕湾', 'PELICAN BAY'],
].map(([key, a, b, cn, en], i) => ({ i, key, a: a * KM, b: b * KM, kmA: a, kmB: b, cn, en }));
export const STRETCH = Object.fromEntries(STRETCHES.map(s => [s.key, s]));

// position within the lap and the lap number of a road distance
export const lapPos = D => wrap(D, LAP);
export const lapOf = D => Math.floor(D / LAP);
export function stretchAt(D) {
  const p = lapPos(D);
  for (const s of STRETCHES) if (p < s.b) return s;
  return STRETCHES[STRETCHES.length - 1];
}
// 0..1 progress through the current stretch
export const stretchProgress = D => { const s = stretchAt(D), p = lapPos(D); return (p - s.a) / (s.b - s.a); };
// signed distance (u) from D to the nearest occurrence of lap position P (landmarks repeat once per lap)
export const relTo = (D, P) => wrap(D - P + LAP / 2, LAP) - LAP / 2;

// Deterministic hash → [0,1) for (index, salt): the streamed props are keyed by their absolute index, so the stream
// never repeats (no Math.random, no state).
export function hash(i, salt = 0) {
  let x = (Math.imul((i | 0) ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(salt + 0x632be5ab | 0, 0xc2b2ae35)) >>> 0;
  x ^= x >>> 16; x = Math.imul(x, 0x7feb352d) >>> 0; x ^= x >>> 15; x = Math.imul(x, 0x846ca68b) >>> 0; x ^= x >>> 16;
  return (x >>> 0) / 4294967296;
}

// Road-side furniture that marks the route: a sign before every stretch, a stone every km.
export const SIGNS = STRETCHES.map(s => ({ stretch: s, at: wrap(s.a - 0.35 * KM, LAP) }));
export const KM_STONES = Array.from({ length: 26 }, (_, k) => ({ km: k, at: k * KM + 0.5 * KM }));

// Easter eggs (lap position, what). Documented for judges; each module implements its own.
export const EGGS = [
  { key: 'pelican-crossing', at: 0.95 * KM, what: 'a zebra "PELICAN CROSSING 鹈鹕过街" with a Belisha beacon in the village' },
  { key: 'statue', at: 0.7 * KM, what: 'a bronze statue of a pelican on a bicycle on the promenade' },
  { key: 'catch', at: 2.5 * KM, what: 'a fisherman on the long pier lands a fish just as you ride past' },
  { key: 'race', at: 7.6 * KM, what: 'the coast-railway steam train races the pelican, the driver waves, TOOT!' },
  { key: 'serpent', at: 14.2 * KM, what: 'a sea serpent loops through the waves under the cliffs' },
  { key: 'bottle', at: 16.6 * KM, what: 'a message in a bottle washed up in the dunes' },
  { key: 'whale', at: 20.4 * KM, what: 'a whale spouts off the old fort' },
  { key: 'welcome', at: 24.2 * KM, what: 'the village bunting reads 欢迎回来 WELCOME BACK on the way home' },
];

